import { AIMode, StudentLevel } from '../types';

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  references?: string[];
  iraabBreakdown?: {
    word: string;
    role: string;
    sign: string;
    explanation: string;
  }[];
  tipsForExam?: string[];
  suggestedAction?: {
    label: string;
    tab?: 'dashboard' | 'reader' | 'ai-tutor' | 'exams' | 'notes' | 'flashcards';
    bookId?: string;
  };
  isLiveGemini?: boolean;
}

export interface AIResponse {
  answer: string;
  iraabBreakdown?: {
    word: string;
    role: string;
    sign: string;
    explanation: string;
  }[];
  references?: string[];
  tipsForExam?: string[];
  suggestedAction?: {
    label: string;
    tab?: 'dashboard' | 'reader' | 'ai-tutor' | 'exams' | 'notes' | 'flashcards';
    bookId?: string;
  };
  isLiveGemini?: boolean;
}

export const SYSTEM_PROMPT_ISLAMIC_SCHOLARLY = `
آپ "تحریکِ ایمان ڈیجیٹل دار الافتاء و رفیقِ مفتی" (Tehreek-e-Iman Digital Dar-ul-Ifta & Mufti Assistant — Gemini Islamic AI) کے جید، باوقار، معتمد اور مستند مفتی و محقق ہیں۔

### بنیادی مقصد و مشن (Dar-ul-Ifta Mission):
ویب سائٹ کے اندر ایک مکمل اور فعال "دار الافتاء" کی ضرورت کو پوری دیانت داری، فقہی باریکی اور کتاب و سنت کی اصل نصوص کے ساتھ پورا کرنا، تاکہ ہر سائل، طالب علم اور عالم کو اس کے سوال کا مدلل اور تسلی بخش شرعی فتویٰ و جواب حاصل ہو۔

### زبان و اندازِ فہم (Languages & Comprehension):
* سائل خواہ سلیس اردو، رومن اردو (Roman Urdu مثلاً "kya talaq gusse me ho jati hai", "namaz k faraiz kya hain"), عربی، یا انگریزی میں استفسار کرے، آپ اس کے سوال کو پوری گہرائی سے سمجھ کر انتہائی فصیح، سلیس، اور باوقار علمی اردو میں جواب عنایت فرمائیں۔
* انداز ہمیشہ ایک مشفق مفتی، مہربان استاذ اور باوقار عالمِ دین جیسا ہو۔

### روایتی باوقار اسلوبِ افتاء (Standard Dar-ul-Ifta Structure):
ہر سوال کے جواب کو درج ذیل روایتی اور باقاعدہ دار الافتاء کے فتوائی اسلوب پر مرتب فرمائیں:

1. **مسنون آغاز:**
   «بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ»
   «الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى سَيِّدِ الْأَنْبِيَاءِ وَالْمُرْسَلِينَ»
   «الْجَوَابُ وَبِاللَّهِ التَّوْفِيقُ:»

2. **خلاصۂ فتویٰ و دو ٹوک شرعی حکم (The Direct Ruling):**
   پہلے ۱ یا ۲ پیراگراف میں سائل کے پوچھے گئے مسئلے کا واضح، دو ٹوک اور غیر مبہم شرعی حکم (فرض، واجب، سنت، مباح، مکروہِ تنزیہی، مکروہِ تحریمی، یا حرام) صاف اور دو ٹوک الفاظ میں بیان فرمائیں تاکہ سائل کو بنیادی اشکال کا فوری حل ملے۔

3. **دلائل من القرآن الکریم (Quranic Evidences):**
   متعلقہ قرآنی آیات مع اعراب (تلاوت کی شکل میں)، سورۃ کا نام، آیت نمبر، اور جامع اردو ترجمہ پیش کریں۔

4. **دلائل من الاحادیث النبویۃ المطہرۃ (Hadith Evidences):**
   صحاحِ ستہ (صحیح البخاری، صحیح مسلم، سنن أبی داود، جامع الترمذی، سنن النسائی، سنن ابن ماجہ) یا دیگر معتمد کتبِ حدیث (موطأ امام مالک، مسند احمد، شرح معانی الآثار للطحاوی) سے حدیث مبارکہ کا عربی متن، اردو ترجمہ، اور صریح حوالہ مع کتاب و باب و حدیث نمبر نقل کریں۔

5. **فقہی نصوص و مراجعِ احناف (Classical Fiqh Authorities):**
   فقہِ حنفی کی امہات الکتب سے نصوص، عبارات اور استدلال پیش فرمائیں:
   - الہدایۃ فی شرح بدایۃ المبتدی للمرغینانی
   - رد المحتار علی الدر المختار (فتاویٰ شامی) لابن عابدین
   - الفتاویٰ الہندیہ (فتاویٰ عالمگیری)
   - بدائع الصنائع فی ترتیب الشرائع للإمام الکاسانی
   - المبسوط للإمام السرخسی
   - مختصر القدوری، نور الایضاح وغیرہ۔
   *اگر سائل نے تقابلِ مذاہب پوچھا ہو تو ائمہ اربعہ (احناف، شوافع، مالکیہ، حنابلہ) کا تفصیلی موقف ان کے دلائل کے ساتھ ذکر فرمائیں۔*

6. **جدید معاملات پر فقہی تطبیق (Modern Financial & Medical Issues):**
   اگر سوال جدید مسائل (آن لائن کاروبار، کرپٹو کرنسی، بینکنگ، انشورنس، میڈیکل آپریشن، ٹرانسپلانٹیشن، خاندانی تنازعات) سے متعلق ہو تو جدید فقہی اکیڈمیز اور فقہی قواعد (الأمور بمقاصدها، المشقة تجلب التيسير، لا ضرر ولا ضرار) کے تحت مدلل رہنمائی فرمائیں۔

7. **مہرِ فتویٰ و اختتام:**
   جواب کے اختتام پر باوقار روایتی کلمۂ توثیق درج فرمائیں:
   «وَاللَّهُ سُبْحَانَهُ وَتَعَالَىٰ أَعْلَمُ بِالصَّوَابِ»
   (اور اللہ پاک ہی سب سے زیادہ درست علم رکھنے والا ہے)۔
   اور اس کے بعد یہ فائنل اختتامی سطر لازماً درج فرمائیں:
   "نوٹ: یہ اے آئی مسئلے کی وضاحت میں معاون ہے، اس کی تصدیق کے لیے اپنے علاقے کے معتبر عالم دین اور مفتیان کرام سے رجوع فرمائیں۔"
`;

export async function askIslamicAI(
  prompt: string,
  mode: AIMode = 'darulifta_fatwa',
  level: StudentLevel = 'intermediate',
  apiKey?: string,
  bookContext?: string,
  conversationHistory: ChatMessage[] = []
): Promise<AIResponse> {
  // Extract effective Gemini API key from explicit prop, localStorage, or environment variables
  const effectiveKey = 
    (apiKey && apiKey.trim()) ||
    (typeof window !== 'undefined' && localStorage.getItem('madrasa_gemini_api_key')?.trim()) ||
    (typeof import.meta !== 'undefined' && (import.meta as any).env?.VITE_GEMINI_API_KEY?.trim()) ||
    '';

  // 1. If Gemini API Key is provided or configured in environment, call Google Gemini Live API
  if (effectiveKey && effectiveKey !== '') {
    const modelsToTry = [
      'gemini-3.6-flash',
      'gemini-flash-latest',
      'gemini-3.7-flash',
      'gemini-2.5-flash',
      'gemini-1.5-flash'
    ];

    const modeInstruction = getModeInstruction(mode, level, bookContext);
    const historyContents = conversationHistory.slice(-10).map(msg => ({
      role: msg.role === 'user' ? 'user' : 'model',
      parts: [{ text: msg.content }]
    }));

    const contents = [
      {
        role: 'user',
        parts: [{ text: `${SYSTEM_PROMPT_ISLAMIC_SCHOLARLY}\n\n${modeInstruction}` }]
      },
      {
        role: 'model',
        parts: [{ text: 'سمعاً وطاعة۔ میں تحریکِ ایمان ڈیجیٹل دار الافتاء کا خادم و محقق ہوں اور قرآنِ حکیم، سنتِ رسول ﷺ اور فقہِ اسلامی کی معتمد کتب کی روشنی میں مدلل رہنمائی اور فتاویٰ پیش کرنے کا پابند ہوں۔' }]
      },
      ...historyContents,
      {
        role: 'user',
        parts: [{ text: prompt }]
      }
    ];

    for (const modelName of modelsToTry) {
      try {
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${effectiveKey}`;
        const response = await fetch(url, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            contents,
            generationConfig: {
              temperature: 0.25,
              maxOutputTokens: 3000,
            }
          }),
        });

        if (response.ok) {
          const data = await response.json();
          const generatedText = data.candidates?.[0]?.content?.parts?.[0]?.text;
          if (generatedText) {
            return {
              answer: generatedText,
              isLiveGemini: true,
              references: bookContext 
                ? [bookContext, "القرآن الکریم", "صحاحِ ستہ", "کتبِ فقہ و فتاویٰ"] 
                : ["القرآن الکریم", "صحیح البخاری و صحیح مسلم", "کتبِ فقہ و فتاویٰ احناف (شامی، ہدایہ، قدوری)"],
              tipsForExam: [
                "قرآنی آیات اور احادیث کے مستند حوالے دار الافتاء کے فتاویٰ کو پختہ اور معتمد بناتے ہیں",
                "مسئلے میں فقہِ حنفی کی امہات الکتب کا صفحہ و جلد نقل کرنا اعلیٰ علمی درجے کا مظہر ہے"
              ]
            };
          }
        }
      } catch (modelErr) {
        console.warn(`Gemini model ${modelName} attempt failed:`, modelErr);
      }
    }
  }

  // 2. Comprehensive Multilingual & Roman-Urdu Scholarly Engine (Offline / Local Fallback)
  return generateOfflineScholarlyResponse(prompt, mode, level, bookContext);
}

function getModeInstruction(mode: AIMode, level: StudentLevel, bookContext?: string): string {
  const contextText = bookContext ? `یہ استفسار کتاب [${bookContext}] کے مطالعہ کے سیاق میں ہے۔` : '';
  
  switch (mode) {
    case 'darulifta_fatwa':
      return `${contextText}
مطلوبہ اسلوب: باقاعدہ اور روایتی دار الافتاء کی طرز پر مستند شرعی فتویٰ تحریر فرمائیں۔ پہلے دو ٹوک حکمِ شرعی (فرض، واجب، سنت، مباح، مکروہ یا حرام) بیان کریں، پھر قرآنی آیات مع سورت و آیت، صحاحِ ستہ سے احادیث مبارکہ مع کتاب و باب، اور فقہِ حنفی کی امہات الکتب (الہدایہ، فتاویٰ شامی، فتاویٰ عالمگیری، قدوری، بدائع الصنائع) کے ٹھوس حوالہ جات اور عبارات پیش فرمائیں۔ اختتام "واللہ سبحانہ وتعالیٰ اعلم بالصواب" پر کریں اور آخر میں یہ سطر لازماً درج فرمائیں: "نوٹ: یہ اے آئی مسئلے کی وضاحت میں معاون ہے، اس کی تصدیق کے لیے اپنے علاقے کے معتبر عالم دین اور مفتیان کرام سے رجوع فرمائیں۔"`;

    case 'dalayel_quran_sunnah':
      return `${contextText}
مطلوبہ اسلوب: قرآنِ مجید کی نصوص اور سنتِ رسول اللہ ﷺ کی روشنی میں ٹھوس، مدلل اور مستند جواب عنایت فرمائیں۔ سورۃ کا نام، آیت نمبر، اور کتبِ حدیث مع ابواب صراحت کے ساتھ نقل کریں۔`;

    case 'madhahib_comparative':
      return `${contextText}
مطلوبہ اسلوب: اس مسئلے میں ائمہ اربعہ (احناف، شوافع، مالکیہ، حنابلہ) کا تفصیلی تقابلی موقف ان کے اپنے اپنے دلائل اور وجۂ استدلال کے ساتھ پیش کریں۔`;

    case 'takhrij_hadith':
      return `${contextText}
مطلوبہ اسلوب: اس حدیث یا روایت کی مکمل تخریج فرمائیں۔ کن کتب میں یہ مروی ہے، راوی کون ہیں اور محدثین کے نزدیک صحت و ضعف کا کیا حکم ہے؟`;

    case 'hal_ibarat':
      return `${contextText}
مطلوبہ اسلوب: اس عربی عبارت پر مکمل اعراب لگائیں، ہر کلمے کی نحوی حیثیت (عامل و معمول، فاعل، مفعول، مبتدا، خبر وغیرہ) جدول کی صورت میں پیش کریں اور جملے کی کلی ترکیب واضح کریں۔`;

    case 'tashreeh':
      return `${contextText}
مطلوبہ اسلوب: اس عبارت کی درسی تشریح [طالب علم کی سطح: ${level}] کے موافق سلیس اور واضح انداز میں پیش فرمائیں۔`;

    case 'exam_prep':
      return `${contextText}
مطلوبہ اسلوب: وفاق المدارس العربیہ کے سالانہ امتحانات کے نقطۂ نظر سے بتائیں کہ اس پر کیا سوالات بنتے ہیں، مثالی جواب کا خاکہ کیا ہونا چاہیے اور نمبر حاصل کرنے کے کلیدی نکات کیا ہیں؟`;

    case 'objections':
      return `${contextText}
مطلوبہ اسلوب: اس عبارت یا مسئلے پر وارد ہونے والے علمی اعتراضات (إن قيل / قلنا) اور ان کے مسکت جوابات مع حوالہ جات پیش کریں۔`;
  }
}

// Normalizes input across English, Roman Urdu, Arabic and Urdu
function normalizeText(text: string): string {
  return text
    .toLowerCase()
    .replace(/[.,:;!?()،؛؟"«»۝0-9٠-٩\-_/\\#\[\]{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


