export interface TopicRule {
  id: string;
  name: string;
  exactPhrases: string[];
  primaryKeywords: string[];
  requiredContext?: string[];
  forbiddenKeywords?: string[];
  handler: (rawPrompt: string, p: string, bookContext?: string) => AIResponse;
}
